static int ssl_write_truncated_hmac_ext ( mbedtls_ssl_context * ssl , unsigned char * buf , const unsigned char * end , size_t * olen ) { unsigned char * p = buf ; * olen = 0 ; MBEDTLS_SSL_DEBUG_MSG ( 3 , ( "client hello, adding truncated_hmac extension" ) ) ; MBEDTLS_SSL_CHK_BUF_PTR ( p , end , 4 ) ; MBEDTLS_PUT_UINT16_BE ( MBEDTLS_TLS_EXT_TRUNCATED_HMAC , p , 0 ) ; p += 2 ; * p ++ = 0x00 ; * p ++ = 0x00 ; * olen = 4 ; return ( 0 ) ; } 